#include "phone_hash.h"
#include "data_files.h"
#include <SD_MMC.h>
#include <mbedtls/sha256.h>
namespace{File file;String path,result;uint32_t expected=0,offset=0,modified=0;bool ready=false,failed=false;mbedtls_sha256_context sha;bool initialized=false;}
void pikaPhoneHashCancel(){if(file)file.close();if(initialized){mbedtls_sha256_free(&sha);initialized=false;}path="";result="";ready=failed=false;}
int pikaPhoneHashRequest(const String& name,String& digest){if(!pikaDataRelativePath(name))return 400;if(path==name&&ready){File check=SD_MMC.open("/notes/"+name);bool same=check&&check.size()==expected&&check.getLastWrite()==modified;if(check)check.close();if(!same)pikaPhoneHashCancel();}if(path!=name){pikaPhoneHashCancel();path=name;file=SD_MMC.open("/notes/"+name);if(!file||file.isDirectory()){pikaPhoneHashCancel();return 404;}expected=file.size();modified=file.getLastWrite();offset=0;mbedtls_sha256_init(&sha);initialized=true;failed=mbedtls_sha256_starts(&sha,0)!=0;}if(!ready&&!failed&&expected<=8192){for(int i=0;i<5&&!ready&&!failed;i++)pikaPhoneHashTick();}if(failed){pikaPhoneHashCancel();return 409;}if(ready){digest=result;return 200;}return 202;}
void pikaPhoneHashTick(){if(!initialized||ready||failed||!file)return;uint8_t block[2048];size_t n=std::min<size_t>(sizeof(block),expected-offset);if(n){size_t got=file.read(block,n);if(got!=n||mbedtls_sha256_update(&sha,block,got)!=0){failed=true;file.close();return;}offset+=got;}if(offset==expected){uint8_t hash[32];if(file.size()!=expected||file.getLastWrite()!=modified||mbedtls_sha256_finish(&sha,hash)!=0){failed=true;}else{char hex[65];for(int i=0;i<32;i++)sprintf(hex+2*i,"%02x",hash[i]);hex[64]=0;result=hex;ready=true;}file.close();}}
